UPDATE public.sealed_quests AS q SET title = 'A Day In The Life', mission_text = 'Find out what a normal workday looks like in Thailand: start time, lunch, commute. Compare it to yours.', backstory = 'Daily rhythms explain why shops close, when streets get busy and when people eat.', keywords = ARRAY['daily life Thailand', 'work culture Thailand', 'Thailand lifestyle']::text[] WHERE q.id = 'c704c485-bfb3-498f-a51c-e57c9e8a42db'::uuid AND q.trip_id = 'e3a3f0fa-c83a-41b1-8ce4-925c7e30a8df'::uuid AND q.user_id = 'fd99920f-d997-4397-b80c-9495587aa10b'::uuid AND q.kind = 'sealed' AND q.title = 'School Days' AND q.submitted_at IS NULL AND EXISTS (SELECT 1 FROM public.season_quests s WHERE s.trip_id=q.trip_id AND s.user_id=q.user_id AND lower(btrim(s.title))=lower(btrim(q.title))) AND NOT EXISTS (SELECT 1 FROM public.sealed_quests x WHERE x.trip_id=q.trip_id AND x.user_id=q.user_id AND x.id<>q.id AND lower(btrim(x.title))=lower('A Day In The Life')) AND NOT EXISTS (SELECT 1 FROM public.season_quests x WHERE x.trip_id=q.trip_id AND x.user_id=q.user_id AND lower(btrim(x.title))=lower('A Day In The Life'));